import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Stats","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/stats.md","filePath":"en/guide/characters/stats.md"}'),r={name:"en/guide/characters/stats.md"};function n(o,a,l,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>STR, DEX and INT remain the only core stats.</li><li>Stats support handling, control and mental capacity; low DEX should not make ordinary play feel like slow motion.</li><li>Athletics is a skill/specialization. Max Stamina has no final formula.</li></ul><p><span id="stats-overview"></span><span id="responsiveness-comes-first"></span><span id="what-each-stat-could-contribute"></span><span id="stats-support-expertise"></span><span id="int-and-prepared-magic"></span><span id="stamina-capacity-is-still-open"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>STR</td><td>May support heavy equipment, load and demanding physical actions; it is not simply a universal damage multiplier.</td></tr><tr><td>DEX</td><td>May support bounded recovery, balance and control under pressure.</td></tr><tr><td>INT</td><td>May support Active Memory and complex magical patterns; its resource relationships remain open.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>STR, DEX and INT contribute to character attributes.</td><td>Keep these three stats while reconsidering their roles in handling and responsiveness.</td></tr><tr><td>Stats interact with skills when building a character.</td><td>Weapon expertise and magical knowledge remain distinct from raw stats.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/player/stats/skills-stats-and-attributes/" target="_blank" rel="noreferrer">Official UO: skills, stats and attributes</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Strength might help you handle a heavy hammer, but knowing its techniques and judging the right moment should still distinguish a capable fighter.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Athletics may support stamina efficiency, recovery and sustained exertion. A derived Endurance/Stamina Capacity is only a hypothesis; there is no new CON stat or final capacity formula. STR should not be the sole stamina stat, and INT should not be a required investment merely to prepare martial SAs.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/skills.html">Skills</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Spell Memory</a> · <a href="/Syrolands-Public/en/guide/combat/overview.html">Combat</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/characters/stats.html">Stats</a> design specification.</p>',18)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
